43			int opcode = *ptr++;
44			int opsize;
45	
46			switch (opcode) {
47			case TCPOPT_EOL:
48				return true;
49			case TCPOPT_NOP:
50				length--;
51				continue;
52			default:
53				opsize = *ptr++;
54				if (opsize < 2)
55					return true;
56				if (opsize > length)
57					return true;
