81				case TCPOPT_SACK_PERM:
82					if (opsize == TCPOLEN_SACK_PERM)
83						opts->options |= XT_SYNPROXY_OPT_SACK_PERM;
84					break;
85				}
86	
87				ptr += opsize - 2;
88				length -= opsize;
89			}
